-- NEAR-only live curriculum. Previously started attempts retain immutable snapshots.
update quizzes set title='NEAR Knowledge Round' where id='daily-quiz';
delete from quiz_questions where quiz_id='daily-quiz';

-- Only the known professor research briefs are retitled; payout terms and saved work stay intact.
update jobs set title='Research the foundations of NEAR', description='Read the official NEAR source brief, answer its knowledge check and submit a summary to Professor Reed.' where employer_wallet='npc:professor-kofi' and title in ('Research the city archives','Research the city archive');
